from __future__ import annotations

import logging
from math import log2
from typing import Any, Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.snmp import SnmpPdu
from taf.hw.pdu.exceptions import BadPortNumber


def decode_ports(n: str) -> list[int]:
    """
    n='0' -> []
    n='2' -> [1] (2**1)
    n='64' -> [6] (2**6)
    n='70' -> [6, 2, 1] (2**6 + 2**2 + 2**1 = 64 + 4 + 2 = 70)
    """

    def _exponents_base_2(num):
        while num > 0:
            power = int(log2(num))
            yield power
            num = num - 2**power

    return list(_exponents_base_2(int(n)))


class APP6(SnmpPdu):
    """Class provides attributes and private methods to manage a PDU of type APP6"""

    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 10,
        snmp_user: dict[str, Any] | None = None,
        community: str = "private",
    ) -> None:
        """
        :param string host: IP address or domain name of the APP6 device.
        :param float timeout: Response timeout in seconds, default value is 10
        :param dict snmp_user (required only for SNMPv3):
        :param community: Community string used by SNMPv1/2.

        There are only 6 ports and 1 non-readOnly oid.
        It is possible to turn off/on multiple ports at once

        Each port has a value of 2 to the power of port number:
        Example: port 5 = 32 (2 to the power of 5)

        Values range from 0 up to 126:
        all ports off = 0
        all ports on = 126 (2+4+8+16+32+64)

        there is support for values < 0 and > 126,
        by adding or subtracting 128 from oid value
        there will be no change in what ports are on/off:
        Example: -126 = 2 = 130

        """
        super().__init__(host, timeout, snmp_user, community)
        self._version = 1
        self._default_oid = "1.3.6.1.4.1.57318.1.4.3.1.40.1"
        self.new_oid_value = None

    @property
    def _port_setting(self):
        return {
            DeviceStatus.ON: str(self.new_oid_value),
            DeviceStatus.OFF: str(self.new_oid_value),
        }

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port=None):
        """APP6 has only 1 non-readOnly oid, therefore port variable is not used."""
        return self._default_oid

    def _set_port_status(self, port, status):
        if not 1 <= port <= 6:
            raise BadPortNumber(f"Port number is invalid, available ports range from 1 to 6: {port}")
        if status == self.get_port_status(port):
            return
        current_oid_value = int(self._execute_get_cmd(self._build_snmp_oid()))
        new_oid_value = current_oid_value + pow(2, port) * (-1 if status == DeviceStatus.OFF else 1)
        self.new_oid_value = new_oid_value
        oid = self._build_snmp_oid()
        logging.info(f"SNMP: Setting port to {status}: {oid}")
        self._execute_set_cmd(status, oid)

    def get_port_status(self, port):
        if not 1 <= port <= 6:
            raise BadPortNumber(f"Port number is invalid, available ports range from 1 to 6: {port}")
        logging.info(f"SNMP: Fetching status of port: {port}")
        oid = self._build_snmp_oid()
        oid_value = self._execute_get_cmd(oid)
        ports_with_on_status = decode_ports(oid_value)
        return DeviceStatus.ON if port in ports_with_on_status else DeviceStatus.OFF


class PortOidResolver:
    def __init__(self, logical_port):
        if not 1 <= logical_port <= 12:
            raise BadPortNumber(f"Port number is invalid, available ports range from 1 to 12: {logical_port}")
        self.logical_port = logical_port
        self.oid = self._build_snmp_oid(logical_port)
        self.device = int(self.oid.split(".")[-1])
        self.physical_port = logical_port - (self.device - 1) * 6

    @staticmethod
    def _build_snmp_oid(logical_port):
        if 7 <= logical_port <= 12:
            oid = "1.3.6.1.4.1.57318.1.4.3.1.40.2"
        else:
            oid = "1.3.6.1.4.1.57318.1.4.3.1.40.1"  # self._default_oid
        return oid


class APP6Multi(APP6):
    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 10,
        snmp_user: dict[str, Any] | None = None,
        community: str = "private",
    ) -> None:
        super().__init__(host=host, timeout=timeout, snmp_user=snmp_user, community=community)

    def _set_port_status(self, port, status):
        if status == self.get_port_status(port):
            return

        resolver = PortOidResolver(port)
        oid = resolver.oid
        physical_port = resolver.physical_port
        device = resolver.device
        current_oid_value = int(self._execute_get_cmd(oid))
        new_oid_value = current_oid_value + pow(2, physical_port) * (-1 if status == DeviceStatus.OFF else 1)
        self.new_oid_value = new_oid_value

        logging.info(f"SNMP: Setting port {port} ({physical_port} dev. {device}) to {status}")
        self._execute_set_cmd(status, oid)

    def get_port_status(self, port):
        resolver = PortOidResolver(port)
        oid = resolver.oid
        physical_port = resolver.physical_port
        device = resolver.device
        logging.info(f"SNMP: Fetching status of port: {port} ({physical_port} dev. {device})")
        oid_value = self._execute_get_cmd(oid)
        ports_with_on_status = decode_ports(oid_value)
        return DeviceStatus.ON if physical_port in ports_with_on_status else DeviceStatus.OFF
